const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const { nanoid } = require('nanoid');
const cors = require('cors');

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(cors());
app.use(express.urlencoded({ extended: true }));

const db = new sqlite3.Database('./urls.db');

// YAHAN originalUrl kar diya
db.run(`CREATE TABLE IF NOT EXISTS urls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    shortCode TEXT UNIQUE NOT NULL,
    originalUrl TEXT NOT NULL,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
)`);

app.get('/', (req, res) => {
    res.send(`
    <!DOCTYPE html>
    <html>
    <head><title>Simple URL Shortener</title>
    <style>body { font-family: Arial; background: #839129; color: white; display: flex; justify-content: center; align-items: center; height: 100vh; } .container { background: #30c3d4; padding: 30px; border-radius: 15px; width: 90%; max-width: 500px; text-align: center; } input { width: 65%; padding: 12px; border: none; border-radius: 8px; } button { padding: 12px 20px; background: #f0a50e; color: white; border: none; border-radius: 8px; cursor: pointer; margin-left: 10px; } #result { margin-top: 20px; }</style>
    </head>
    <body>
        <div class="container">
            <h1>🚀 Simple URL Shortener</h1>
            <input type="text" id="urlInput" placeholder="https://example.com">
            <button onclick="shortenUrl()">Shorten</button>
            <div id="result"></div>
        </div>
        <script>
            async function shortenUrl() {
                const url = document.getElementById('urlInput').value;
                if(!url) return alert('Please enter URL');
                const res = await fetch('/api/shorten', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ originalUrl: url })});
                const data = await res.json();
                if(res.ok) document.getElementById('result').innerHTML = \`Short URL: <a href="\${data.shortUrl}" target="_blank">\${data.shortUrl}</a>\`;
                else alert(data.error);
            }
        </script>
    </body>
    </html>`);
});

app.post('/api/shorten', (req, res) => {
    const { originalUrl } = req.body; // YAHAN bhi originalUrl
    if(!originalUrl) return res.status(400).json({error: "URL is required"});
    const shortCode = nanoid(6);
    db.run(`INSERT INTO urls (shortCode, originalUrl) VALUES (?,?)`, [shortCode, originalUrl], function(err) {
        if(err) return res.status(500).json({error: err.message});
        res.json({ shortUrl: `http://localhost:${PORT}/${shortCode}` });
    });
});

app.get('/:shortCode', (req, res) => {
    db.get(`SELECT originalUrl FROM urls WHERE shortCode =?`, [req.params.shortCode], (err, row) => { // YAHAN bhi
        if(err) return res.status(500).json({error: err.message});
        if(!row) return res.status(404).send('URL not found');
        res.redirect(row.originalUrl);
    });
});

app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
